  ('dan_tranh_level_1_bai_5_practice','Đàn Tranh',1,1,'2','Nhịp điệu cơ bản','Cô Mai giới thiệu trường độ: nốt trắng, nốt đen, nốt móc đơn và nốt móc kép.','','{"practiceMode":"note_sequence","noteSequence":[],"durations":[],"fingerings":[],"cues":[]}'),
  ('dan_tranh_level_1_bai_4_practice','Đàn Tranh',1,2,'3','Đọc bản nhạc cơ bản','Cô Mai giới thiệu âm vực 17 dây, tempo, khóa Sol, nhịp 4/4 và 2/4.','','{"practiceMode":"note_sequence","noteSequence":[],"durations":[],"fingerings":[],"cues":[]}'),
  ('dan_tranh_level_1_bai_8_practice','Đàn Tranh',1,3,'4.1','Kỹ thuật gảy ngón 2','Dùng ngón 2 gảy lần lượt 5 nốt trên 5 dây đầu: Sol1, La1, Đô2, Rê2 và Mi2. Ứng dụng nhận diện cao độ của từng dây bằng micro.','Hướng dẫn sử dụng ngón trỏ tay phải (ngón 2), giữ bàn tay khum tự nhiên và thả lỏng khi gảy đàn.','{"practiceMode":"note_sequence","noteSequence":["Sol1","La1","Đô2","Rê2","Mi2"],"durations":[1,1,1,1,2],"fingerings":["2","2","2","2","2"],"cues":[]}'),
  ('dan_tranh_level_1_bai_7_practice','Đàn Tranh',1,4,'4.2','Kỹ thuật gảy ngón 1','Dùng ngón 1 gảy lần lượt 5 nốt trên các dây 6 đến 10: Sol2, La2, Đô3, Rê3 và Mi3. Ứng dụng nhận diện cao độ của từng dây bằng micro.','Hướng dẫn sử dụng ngón cái tay phải (ngón 1), giữ cổ tay thả lỏng và gảy dây rõ tiếng.','{"practiceMode":"note_sequence","noteSequence":["Sol2","La2","Đô3","Rê3","Mi3"],"durations":[1,1,1,1,2],"fingerings":["1","1","1","1","1"],"cues":[]}'),
  ('dan_tranh_level_1_bai_9_practice','Đàn Tranh',1,5,'4.3','Kỹ thuật gảy ngón 3','Dùng ngón 3 gảy lần lượt 7 nốt trên các dây 11 đến 17: Sol3, La3, Đô4, Rê4, Mi4, Sol4 và La4. Ứng dụng nhận diện cao độ của từng dây bằng micro.','Hướng dẫn sử dụng ngón giữa tay phải (ngón 3), giữ bàn tay khum tự nhiên và gảy rõ tiếng ở âm vực cao.','{"practiceMode":"note_sequence","noteSequence":["Sol3","La3","Đô4","Rê4","Mi4","Sol4","La4"],"durations":[1,1,1,1,1,1,2],"fingerings":["3","3","3","3","3","3","3"],"cues":[]}'),
  ('dan_tranh_level_1_bai_2_practice','Đàn Tranh',1,6,'5','Luyện gảy các nốt cơ bản – Phần 1','Gảy lần lượt dây 1 đến dây 10: Sol1, La1, Đô2, Rê2, Mi2, Sol2, La2, Đô3, Rê3 và Mi3. Luân phiên ngón 2 rồi ngón 1 từ nốt đầu tiên. Ứng dụng dùng micro nhận diện đúng cao độ từng dây trước khi chuyển sang nốt tiếp theo.','Cách nhận diện cao độ 10 nốt nhạc cơ bản ở âm vực trầm và trung trên Đàn Tranh.','{"practiceMode":"note_sequence","noteSequence":["Sol1","La1","Đô2","Rê2","Mi2","Sol2","La2","Đô3","Rê3","Mi3"],"durations":[1.5,1.5,1.5,1.5,1.5,1.5,1.5,1.5,1.5,2],"fingerings":["2","1","2","1","2","1","2","1","2","1"],"cues":[]}'),
  ('dan_tranh_level_1_bai_3_practice','Đàn Tranh',1,7,'6','Luyện gảy các nốt cơ bản – Phần 2','Gảy lần lượt dây 11 đến dây 17: Sol3, La3, Đô4, Rê4, Mi4, Sol4 và La4. Luân phiên ngón 3, ngón 2 rồi ngón 1 từ nốt đầu tiên. Ứng dụng dùng micro nhận diện đúng cao độ từng dây trước khi chuyển sang nốt tiếp theo.','Cách nhận diện cao độ 7 nốt nhạc ở âm vực cao trên Đàn Tranh.','{"practiceMode":"note_sequence","noteSequence":["Sol3","La3","Đô4","Rê4","Mi4","Sol4","La4"],"durations":[1.5,1.5,1.5,1.5,1.5,1.5,2],"fingerings":["3","2","1","3","2","1","3"],"cues":[]}'),
