), prepared AS (
  SELECT s.*, i.id AS instrument_id,
    CASE
      WHEN s.instrument_name = 'Đàn Tranh' AND s.local_level = 1 THEN 1
      WHEN s.instrument_name = 'Đàn Tranh' AND s.local_level BETWEEN 2 AND 6 THEN 2
      WHEN s.instrument_name = 'Đàn Tranh' THEN 3
      WHEN s.instrument_name = 'Sáo' AND s.local_level <= 2 THEN 1
      WHEN s.instrument_name = 'Sáo' AND s.local_level <= 4 THEN 2
      ELSE 3
    END AS skill_level_order
  FROM source s JOIN instruments i ON i.name = s.instrument_name
), resolved AS (
  SELECT p.*, sl.skill_level_id AS skill_level_id, (SELECT u.user_id FROM users u JOIN roles r ON r.role_id=u.role_id WHERE r.role_name='INSTRUCTOR' ORDER BY u.user_id LIMIT 1) AS instructor_id
  FROM prepared p JOIN skill_levels sl ON sl.order_index=p.skill_level_order
)
INSERT INTO lessons (lesson_code, instrument_id, skill_level_id, created_by_user_id, title, description, approval_status, is_visible, order_index)
SELECT lesson_code, instrument_id, skill_level_id, instructor_id, title, description, 'APPROVED', true, sequence_index + 1
FROM resolved
ON CONFLICT (lesson_code) DO UPDATE SET
  instrument_id=EXCLUDED.instrument_id, skill_level_id=EXCLUDED.skill_level_id,
  title=EXCLUDED.title, description=EXCLUDED.description, approval_status='APPROVED', is_visible=true, order_index=EXCLUDED.order_index;

DELETE FROM lesson_contents c USING lessons l
WHERE c.lesson_id=l.lesson_id AND c.content_type='CURRICULUM_SEED'
  AND (l.lesson_code LIKE 'dan_tranh_%' OR l.lesson_code LIKE 'sao_truc_%' OR l.lesson_code LIKE 'Node%');

