INSERT INTO lesson_contents (lesson_id, content_text, content_type, payload_json, schema_version, order_index)
SELECT l.lesson_id, NULLIF(s.teacher_text,''), 'CURRICULUM_SEED',
 json_build_object('schemaVersion',1,'displayNumber',s.display_number,'teacherText',s.teacher_text,'practiceConfig',s.practice_config::json)::text, '1', 1
FROM source s JOIN lessons l ON l.lesson_code=s.lesson_code;

INSERT INTO exercises (lesson_id, title, description, pass_threshold, order_index, exercise_type, practice_mode, config_json, schema_version)
SELECT l.lesson_id, 'Thực hành: ' || l.title, l.description, 60, 1, 'PRACTICE',
       COALESCE((c.payload_json::json->'practiceConfig'->>'practiceMode'),'note_sequence'),
       c.payload_json, '1'
FROM lessons l JOIN lesson_contents c ON c.lesson_id=l.lesson_id AND c.content_type='CURRICULUM_SEED'
WHERE NOT EXISTS (SELECT 1 FROM exercises e WHERE e.lesson_id=l.lesson_id AND e.order_index=1);

COMMIT;
